6.5 Word Clouds by Subfield

American PoliticsComparative PoliticsInternational RelationsMethodologyPolitical TheoryPublic LawPublic Policy


{r echo=FALSE} wc &lt;- tidy_words %&gt;% filter(subfield == "AP") %&gt;%     count(word, sort = TRUE) %&gt;% slice_head(n = 100)   if (nrow(wc) &gt;= 5) {     wordcloud(wc$word, wc$n, min.freq = 2, max.words = 80,               random.order = FALSE, rot.per = 0.25,               colors = brewer.pal(8, "Dark2"), scale = c(3.5, 0.5))     title(main = "American Politics", cex.main = 1.2)   }


